#include "simp/CodeGenerator.hpp"

#include "simp/Diagnostic.hpp"

#include <iomanip>
#include <sstream>
#include <utility>

namespace simp {
namespace {

std::string llvmBytes(const std::string& bytes) {
    std::ostringstream escaped;
    for (const unsigned char byte : bytes) {
        if (byte >= 0x20 && byte <= 0x7e && byte != '"' && byte != '\\') {
            escaped << static_cast<char>(byte);
        } else {
            escaped << '\\' << std::uppercase << std::hex << std::setw(2) << std::setfill('0')
                    << static_cast<unsigned>(byte) << std::nouppercase << std::dec;
        }
    }
    return escaped.str();
}

} // namespace

CodeGenerator::CodeGenerator(std::string targetTriple)
    : targetTriple_(std::move(targetTriple)) {}

[[noreturn]] void CodeGenerator::unsupported(const SourceLocation& location,
                                             const std::string& feature) const {
    throw DiagnosticError(location, feature + " is not supported by the current LLVM backend");
}

CodeGenerator::Binding CodeGenerator::findVariable(const std::string& name,
                                                   const SourceLocation& location) const {
    for (auto scope = scopes_.rbegin(); scope != scopes_.rend(); ++scope) {
        const auto found = scope->find(name);
        if (found != scope->end()) {
            return found->second;
        }
    }
    throw DiagnosticError(location, "backend could not resolve variable '" + name + "'");
}

std::string CodeGenerator::newTemporary() {
    return "%t" + std::to_string(nextTemporary_++);
}

std::string CodeGenerator::newLabel(const std::string& prefix) {
    return prefix + "." + std::to_string(nextLabel_++);
}

std::string CodeGenerator::internString(const std::string& bytes) {
    const auto name = "@.simp.string." + std::to_string(nextString_++);
    stringGlobals_ += name + " = private unnamed_addr constant [" +
                      std::to_string(bytes.size()) + " x i8] c\"" + llvmBytes(bytes) + "\"\n";
    return name;
}

void CodeGenerator::emitStringBytes(const std::string& bytes) {
    if (bytes.empty()) {
        return;
    }
    const auto global = internString(bytes);
    const auto pointer = newTemporary();
    instructions_ += "  " + pointer + " = getelementptr inbounds [" +
                     std::to_string(bytes.size()) + " x i8], ptr " + global + ", i64 0, i64 0\n";
    const auto stream = newTemporary();
    instructions_ += "  " + stream + " = load ptr, ptr @stdout\n";
    instructions_ += "  call i64 @fwrite(ptr " + pointer + ", i64 1, i64 " +
                     std::to_string(bytes.size()) + ", ptr " + stream + ")\n";
}

CodeGenerator::Value CodeGenerator::emitIntegerExpression(const Expression& expression) {
    if (expression.kind == ExpressionKind::Integer) {
        return {"i32", expression.value, false};
    }
    if (expression.kind == ExpressionKind::Identifier) {
        const auto binding = findVariable(expression.value, expression.location);
        if (binding.isString) {
            throw DiagnosticError(expression.location, "expected int expression");
        }
        const auto temporary = newTemporary();
        instructions_ += "  " + temporary + " = load i32, ptr " + binding.pointer + "\n";
        return {"i32", temporary, false};
    }
    if (expression.kind == ExpressionKind::Unary) {
        const auto operand = emitIntegerExpression(*expression.left);
        if (expression.value == "+") {
            return operand;
        }
        const auto temporary = newTemporary();
        if (expression.value == "-") {
            instructions_ += "  " + temporary + " = sub i32 0, " + operand.operand + "\n";
            return {"i32", temporary, false};
        }
        if (expression.value == "!") {
            const auto boolean = newTemporary();
            instructions_ += "  " + boolean + " = icmp eq i32 " + operand.operand + ", 0\n";
            instructions_ += "  " + temporary + " = zext i1 " + boolean + " to i32\n";
            return {"i32", temporary, false};
        }
        unsupported(expression.location, "unary operator '" + expression.value + "'");
    }
    if (expression.kind == ExpressionKind::Binary) {
        const auto left = emitIntegerExpression(*expression.left);
        const auto right = emitIntegerExpression(*expression.right);
        const auto temporary = newTemporary();
        const auto& operation = expression.value;
        if (operation == "+" || operation == "-" || operation == "*") {
            const char* instruction = operation == "+" ? "add" : operation == "-" ? "sub" : "mul";
            instructions_ += "  " + temporary + " = " + instruction + " i32 " + left.operand +
                             ", " + right.operand + "\n";
            return {"i32", temporary, false};
        }
        if (operation == "/" || operation == "%") {
            const char* instruction = operation == "/" ? "sdiv" : "srem";
            instructions_ += "  " + temporary + " = " + instruction + " i32 " + left.operand +
                             ", " + right.operand + "\n";
            return {"i32", temporary, false};
        }

        std::string predicate;
        if (operation == "==") predicate = "eq";
        else if (operation == "!=") predicate = "ne";
        else if (operation == "<") predicate = "slt";
        else if (operation == "<=") predicate = "sle";
        else if (operation == ">") predicate = "sgt";
        else if (operation == ">=") predicate = "sge";
        else unsupported(expression.location, "operator '" + operation + "'");
        const auto boolean = newTemporary();
        instructions_ += "  " + boolean + " = icmp " + predicate + " i32 " + left.operand +
                         ", " + right.operand + "\n";
        instructions_ += "  " + temporary + " = zext i1 " + boolean + " to i32\n";
        return {"i32", temporary, false};
    }
    if (expression.kind == ExpressionKind::String) {
        throw DiagnosticError(expression.location, "expected int expression");
    }
    unsupported(expression.location, "integer expression");
}

CodeGenerator::Value CodeGenerator::emitExpression(const Expression& expression) {
    if (expression.kind == ExpressionKind::String) {
        const auto global = internString(expression.value);
        const auto aggregate = "{ ptr " + global + ", i64 " +
                               std::to_string(expression.value.size()) + " }";
        return {"%SimpleString", aggregate, true};
    }
    if (expression.kind == ExpressionKind::Identifier) {
        const auto binding = findVariable(expression.value, expression.location);
        const auto temporary = newTemporary();
        const auto type = binding.isString ? "%SimpleString" : "i32";
        instructions_ += "  " + temporary + " = load " + type + ", ptr " + binding.pointer + "\n";
        return {type, temporary, binding.isString};
    }
    return emitIntegerExpression(expression);
}

void CodeGenerator::emitPrint(const Statement& statement) {
    if (statement.expressions.empty()) {
        return;
    }
    if (statement.expressions.size() > 1) {
        const auto& format = *statement.expressions.front();
        std::size_t segmentStart = 0;
        std::size_t argumentIndex = 1;
        for (std::size_t index = 0; index < format.value.size(); ++index) {
            if (format.value[index] != '{') {
                continue;
            }
            emitStringBytes(format.value.substr(segmentStart, index - segmentStart));
            const auto value = emitIntegerExpression(*statement.expressions[argumentIndex++]);
            instructions_ += "  call i32 (ptr, ...) @printf(ptr @.simp.int.format, i32 " +
                             value.operand + ")\n";
            index += 1;
            segmentStart = index + 1;
        }
        emitStringBytes(format.value.substr(segmentStart));
    } else {
        const auto value = emitExpression(*statement.expressions.front());
        if (value.isString) {
            const auto data = newTemporary();
            const auto length = newTemporary();
            instructions_ += "  " + data + " = extractvalue " + value.type + " " + value.operand +
                             ", 0\n";
            instructions_ += "  " + length + " = extractvalue " + value.type + " " + value.operand +
                             ", 1\n";
            const auto stream = newTemporary();
            instructions_ += "  " + stream + " = load ptr, ptr @stdout\n";
            instructions_ += "  call i64 @fwrite(ptr " + data + ", i64 1, i64 " + length +
                             ", ptr " + stream + ")\n";
        } else {
            instructions_ += "  call i32 (ptr, ...) @printf(ptr @.simp.int.format, i32 " +
                             value.operand + ")\n";
        }
    }
    emitStringBytes("\n");
}

void CodeGenerator::emitStatements(const std::vector<Statement>& statements) {
    for (const auto& statement : statements) {
        emitStatement(statement);
    }
}

void CodeGenerator::emitStatement(const Statement& statement) {
    switch (statement.kind) {
    case StatementKind::Declaration: {
        const bool isString = statement.declaredType == "string";
        const auto pointer = "%v" + std::to_string(nextVariable_++);
        scopes_.back().emplace(statement.name, Binding{pointer, isString});
        const std::string type = isString ? "%SimpleString" : "i32";
        entryAllocas_ += "  " + pointer + " = alloca " + type + "\n";
        if (!statement.expressions.empty()) {
            const auto value = emitExpression(*statement.expressions.front());
            instructions_ += "  store " + type + " " + value.operand + ", ptr " + pointer + "\n";
        }
        return;
    }
    case StatementKind::Assignment: {
        const auto binding = findVariable(statement.name, statement.location);
        const auto value = emitExpression(*statement.expressions.front());
        const std::string type = binding.isString ? "%SimpleString" : "i32";
        if (value.type != type) {
            throw DiagnosticError(statement.location, "backend assignment type mismatch");
        }
        instructions_ += "  store " + type + " " + value.operand + ", ptr " + binding.pointer + "\n";
        return;
    }
    case StatementKind::Print:
        emitPrint(statement);
        return;
    case StatementKind::Block:
        scopes_.emplace_back();
        emitStatements(statement.body);
        scopes_.pop_back();
        return;
    case StatementKind::If: {
        const auto condition = emitIntegerExpression(*statement.expressions.front());
        const auto conditionFlag = newTemporary();
        const auto thenLabel = newLabel("if.then");
        const auto elseLabel = newLabel("if.else");
        const auto endLabel = newLabel("if.end");
        instructions_ += "  " + conditionFlag + " = icmp ne i32 " + condition.operand + ", 0\n";
        instructions_ += "  br i1 " + conditionFlag + ", label %" + thenLabel + ", label %" +
                         (statement.hasAlternate ? elseLabel : endLabel) + "\n";
        instructions_ += thenLabel + ":\n";
        scopes_.emplace_back();
        emitStatements(statement.body);
        scopes_.pop_back();
        instructions_ += "  br label %" + endLabel + "\n";
        if (statement.hasAlternate) {
            instructions_ += elseLabel + ":\n";
            scopes_.emplace_back();
            emitStatements(statement.alternate);
            scopes_.pop_back();
            instructions_ += "  br label %" + endLabel + "\n";
        }
        instructions_ += endLabel + ":\n";
        return;
    }
    case StatementKind::While: {
        const auto conditionLabel = newLabel("while.cond");
        const auto bodyLabel = newLabel("while.body");
        const auto endLabel = newLabel("while.end");
        instructions_ += "  br label %" + conditionLabel + "\n";
        instructions_ += conditionLabel + ":\n";
        const auto condition = emitIntegerExpression(*statement.expressions.front());
        const auto conditionFlag = newTemporary();
        instructions_ += "  " + conditionFlag + " = icmp ne i32 " + condition.operand + ", 0\n";
        instructions_ += "  br i1 " + conditionFlag + ", label %" + bodyLabel + ", label %" +
                         endLabel + "\n";
        instructions_ += bodyLabel + ":\n";
        scopes_.emplace_back();
        emitStatements(statement.body);
        scopes_.pop_back();
        instructions_ += "  br label %" + conditionLabel + "\n";
        instructions_ += endLabel + ":\n";
        return;
    }
    }
}

std::string CodeGenerator::generate(const Program& program) {
    scopes_.clear();
    scopes_.emplace_back();
    instructions_.clear();
    entryAllocas_.clear();
    stringGlobals_.clear();
    nextTemporary_ = 0;
    nextVariable_ = 0;
    nextLabel_ = 0;
    nextString_ = 0;
    emitStatements(program.statements);

    std::ostringstream module;
    module << "source_filename = \"simple\"\n"
           << "target triple = \"" << targetTriple_ << "\"\n\n"
           << "%SimpleString = type { ptr, i64 }\n"
           << "@.simp.int.format = private unnamed_addr constant [3 x i8] c\"%d\\00\"\n"
           << "@stdout = external global ptr\n"
           << stringGlobals_ << "\n"
           << "declare i32 @printf(ptr, ...)\n"
           << "declare i64 @fwrite(ptr, i64, i64, ptr)\n\n"
           << "define i32 @main() {\n"
           << "entry:\n"
           << entryAllocas_
           << instructions_
           << "  ret i32 0\n"
           << "}\n";
    return module.str();
}

} // namespace simp
